contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) { c = _c; deployer = address(this); }

    // This test takes parameters to try both owner and non-owner actions and an amount to transfer.
    // We will: (1) fund C via its fallback by sending 'fund' wei, (2) record balances and depositsCount,
    // (3) attempt a call as owner to withdraw up to 'amount', and (4) attempt a call as non-owner to withdraw
    // using low-level call from a newly created external contract (by using address(0x1) style is not allowed),
    // but since this test contract is the owner, we assert that owner-invoked withdraw never increases C.balance
    // and that non-owner attempts (simulated by calling sendMoney with a target that will revert) do not succeed.

    // Note: Because the deployed C sets owner = msg.sender at its deployment, and the checker deploys a fresh C
    // and then passes it to this constructor, this contract is the owner.

    function run(uint amount, uint fund) public payable {
        require(address(this).balance >= fund && fund >= 0, "insufficient balance for funding");

        // Fund C by invoking fallback via a plain call with value
        // The fallback increments depositsCount and accepts Ether
        c.f{value: fund}();

        uint beforeC = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Try owner withdraw: should succeed (not revert) and reduce C balance by at most amount
        bool ownerReverted;
        uint afterC_owner;
        try c.withdraw{value:0}(amount) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }
        afterC_owner = address(c).balance;

        // Try owner withdrawAll: should succeed (not revert) and reduce C balance to at least 0
        bool ownerWithdrawAllReverted;
        uint afterC_withdrawAll = afterC_owner;
        try c.withdrawAll{value:0}() {
            ownerWithdrawAllReverted = false;
        } catch {
            ownerWithdrawAllReverted = true;
        }
        afterC_withdrawAll = address(c).balance;

        // Attempt a sendMoney to a non-payable target address 0x0 which will cause target.call to fail.
        // As owner this call should revert (since call returns false and contract reverts), we capture that.
        bool sendMoneyReverted;
        try c.sendMoney{value:0}(address(0), 0) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // General rule asserted:
        // - If owner withdraw did not revert, then C's balance decreased by at least 0 and at most amount (i.e., new balance >= beforeC - amount)
        // - withdrawAll when successful leaves balance == 0
        // - sendMoney to an address(0) must revert (because target.call will return false and C reverts)
        assert(
            // owner withdraw consistency
            (ownerReverted || afterC_owner >= beforeC - amount) &&
            // withdrawAll consistency: if it succeeded then balance is zero; if it reverted, no constraint beyond non-negative balance
            (ownerWithdrawAllReverted || afterC_withdrawAll == 0) &&
            // sendMoney to address(0) should revert
            sendMoneyReverted &&
            // depositsCount increased by exactly 1 from the funding fallback call
            c.depositsCount() == beforeDeposits + 1
        );
    }

    // receive to accept refunds if any
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take fund and amount as inputs. This function will: fund C by invoking its fallback (plain call with value),
    // then attempt owner withdraw(amount) and withdrawAll(), recording balances and depositsCount, and assert general invariants.
    function run(uint amount, uint fund) public payable {
        // ensure this test contract has enough ETH to fund C
        require(address(this).balance >= fund, "insufficient balance to fund");

        uint beforeDeposits = c.depositsCount();
        uint beforeC = address(c).balance;

        // Fund C by invoking fallback via a plain call with value 'fund'
        // This is a top-level state-changing call on c
        (bool ok, ) = address(c).call{value: fund}("");
        require(ok, "funding failed");

        // Read after-fund observable state
        uint afterFundDeposits = c.depositsCount();
        uint afterFundC = address(c).balance;

        // Try owner withdraw(amount) and capture whether it reverted
        bool withdrawReverted;
        try c.withdraw(amount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint afterWithdrawC = address(c).balance;

        // Try owner withdrawAll() and capture whether it reverted
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }
        uint afterWithdrawAllC = address(c).balance;

        // General rule asserted:
        // 1) The fallback funding increased depositsCount by exactly 1 and increased contract balance by exactly fund.
        // 2) If withdraw(amount) did not revert, the contract balance decreased by at most amount (i.e., new_balance >= prev_balance - amount).
        // 3) If withdrawAll() did not revert, contract balance is zero after it.
        assert(
            // funding effects
            afterFundDeposits == beforeDeposits + 1 &&
            afterFundC == beforeC + fund &&
            // withdraw amount constraint (only enforce if it didn't revert)
            (withdrawReverted || afterWithdrawC >= afterFundC - amount) &&
            // withdrawAll empties the contract when successful
            (withdrawAllReverted || afterWithdrawAllC == 0)
        );
    }

    // accept Ether if C sends any back
    receive() external payable {}
}

