contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Attempt to withdraw as non-owner: parameters choose an amount and whether to call withdrawAll or withdraw
    function run(bool callWithdrawAll, uint amount) public payable {
        // ensure this test contract has enough balance if it will forward value to C (not needed here but kept general)
        require(address(this).balance >= 0);

        // Observe initial public values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Make a call that should only succeed for owner (this contract is NOT the owner)
        bool reverted;
        if (callWithdrawAll) {
            try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        } else {
            try c.withdraw(amount) { reverted = false; } catch { reverted = true; }
        }

        // After the attempted withdrawal, the contract's public state must be unchanged if call reverted.
        // If it did not revert, it must be because this contract is owner — but in the test scenario deployed c had owner = deployer (not this contract),
        // so we assert that the call reverted and depositsCount and balance are unchanged.
        assert(reverted == true && c.depositsCount() == beforeDeposits && address(c).balance == beforeBalance);
    }

    // Allow receiving Ether in case it's needed externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Call C with arbitrary target calldata (ignored) and an Ether amount to trigger fallback
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Observe before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Perform a plain top-level state-changing call to C, forwarding `amount` wei.
        bool reverted;
        try c.sendMoney(address(c), 0) {
            // sendMoney here is only to exercise a state-changing call path without sending Ether to C itself.
            reverted = false;
        } catch {
            reverted = true;
        }

        // Now make an actual external transfer to C to trigger its fallback; must be a top-level statement.
        // Use low-level call via address(c).call to send Ether to C (this is allowed from the test), but
        // per constraints we must observe effects only via public getters and balances. This call can revert.
        bool sendReverted;
        (bool ok, ) = address(c).call{value: amount}("");
        sendReverted = !ok;

        // Read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: if the external plain Ether transfer did NOT revert, depositsCount increases by exactly 1
        // and C's balance increases by exactly `amount`. If it reverted, neither should increase due to that transfer.
        assert(sendReverted ? (afterDeposits == beforeDeposits && afterBalance == beforeBalance) : (afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an initial deposit amount to send to c (to increase its balance via fallback),
    // and then call withdrawAll. The test asserts that if withdrawAll does not revert, it
    // empties the contract balance and leaves depositsCount unchanged.
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Observe before-values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Send Ether to C to trigger its fallback and increase balance (top-level call on c is not possible for fallback,
        // so we send Ether by calling c.sendMoney to a payable address that forwards to c: use c.sendMoney with target = address(this)
        // then have this contract forward to c in receive(). However, constraints forbid helper calls nested; instead we can
        // directly send Ether to c by using c.sendMoney with target = address(c) — sendMoney is onlyOwner, and this test contract is owner,
        // because the checker deploys C and then this test contract is the caller? According to constraints, the checker deploys a FRESH c and
        // runs run(...) with msg.sender = InvMutTest contract and this contract deployed c. Therefore this contract is owner. So we can call:
        c.sendMoney(address(c), depositAmount);

        // Read intermediate values after deposit
        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // Now attempt withdrawAll and catch whether it reverts
        bool withdrewReverted;
        try c.withdrawAll() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Read after-values
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: if withdrawAll did not revert, it must set contract balance to 0 and must not change depositsCount
        assert(withdrewReverted ? (afterDeposits == midDeposits && afterBalance == midBalance) : (afterBalance == 0 && afterDeposits == midDeposits));
    }

    // receive to accept Ether forwarded by C when sendMoney targets address(c)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // We take two parameters: callerIsOwner selects whether this contract will call as owner (true)
    // or simulate a non-owner by making the call through address(0x1) via low-level call; amount is used for value-sending calls.
    // Note: msg.sender for calls to c will always be this contract, so to simulate non-owner we attempt to invoke c functions
    // from a different address by calling c through a forwarded call (not possible). Instead, we check that when this contract
    // is the owner it can withdraw, and if we first transfer ownership away by a failing pattern we detect revert. Since C exposes owner only via public getter,
    // we use the fact owner was set to the deployer of C (the test harness deployer) — but per harness rules, C is freshly deployed with InvMutTest as deployer.

    // To produce meaningful owner/non-owner behavior we rely on how C was constructed: owner == msg.sender at C construction,
    // and the checker deploys a fresh C with InvMutTest as msg.sender, so this contract is the owner. We therefore assert that calls to withdraw with
    // arbitrary amounts do not revert when invoked by this contract, and that depositsCount only changes via fallback.

    // The single public test function below exercises withdraw and sendMoney and asserts general rules about ownership enforcement and depositsCount monotonicity.
    function run(uint sendValue, address target, uint sendMoneyValue) public payable {
        require(address(this).balance >= sendValue, "insufficient balance for test send");
        require(address(this).balance >= sendMoneyValue, "insufficient balance for sendMoney");

        // Record before values
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;

        // Call fallback by sending Ether to c (this will increment depositsCount)
        // Use low-level call to trigger fallback: calling nonexistent function via address(c).call with value
        (bool okFallback, ) = address(c).call{value: sendValue}("");
        // We don't require success; fallback is payable so okFallback should be true when value sent.

        uint afterDeposits = c.depositsCount();
        uint afterBalanceC = address(c).balance;

        // Try withdraw of some amount from c by this contract (InvMutTest is owner). Catch revert flag.
        bool withdrewReverted;
        try c.withdraw(sendValue) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Try sendMoney to target address (owner-only). Catch revert flag.
        bool sendMoneyReverted;
        try c.sendMoney(target, sendMoneyValue) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // General rule asserted:
        // 1) depositsCount increases by exactly 1 iff the attempt to send Ether to fallback succeeded (i.e., afterBalanceC == beforeBalanceC + sendValue)
        // 2) withdraw by the owner must NOT revert when amount <= address(c).balance before the withdraw call
        // 3) sendMoney by the owner may revert if target call fails; but if sendMoney did NOT revert then address(c).balance decreased by sendMoneyValue

        // Evaluate conditions used in the assert
        bool fallbackSucceeded = (afterBalanceC == beforeBalanceC + sendValue);
        bool depositsIncremented = (afterDeposits == beforeDeposits + (fallbackSucceeded ? 1 : 0));

        bool sufficientForWithdraw = (sendValue <= afterBalanceC || sendValue <= beforeBalanceC || sendValue <= address(c).balance);
        // We assert a rule tying these together:
        // - depositsCount matches whether the fallback value arrived
        // - if withdraw amount is <= c.balance at time of call, withdraw must not revert
        // - if sendMoney did not revert, c.balance must have decreased by sendMoneyValue
        uint finalBalanceC = address(c).balance;
        bool sendMoneyBalanceEffect = true;
        if (!sendMoneyReverted) {
            // If sendMoney succeeded, c's balance must have decreased by exactly sendMoneyValue (unless payment to target re-entrantly changed it further),
            // but C performs a single call transferring sendMoneyValue; we check at least that balance decreased by >= sendMoneyValue.
            sendMoneyBalanceEffect = (afterBalanceC >= sendMoneyValue ? finalBalanceC + sendMoneyValue <= afterBalanceC + (finalBalanceC - finalBalanceC) : finalBalanceC + sendMoneyValue <= afterBalanceC + sendMoneyValue);
            // To avoid complex arithmetic and potential underflow, simplify to require finalBalanceC <= afterBalanceC;
            sendMoneyBalanceEffect = finalBalanceC <= afterBalanceC;
        }

        // Compose the final assert combining the above meaningful properties.
        assert(depositsIncremented && ( !( (sendValue <= afterBalanceC) && withdrewReverted ) ) && (sendMoneyReverted || sendMoneyBalanceEffect));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: valueToSend triggers fallback, withdrawAmount attempts to withdraw, sendTarget and sendValue used for sendMoney
    function run(uint valueToSend, uint withdrawAmount, address sendTarget, uint sendValue) public payable {
        require(address(this).balance >= valueToSend, "insufficient balance for fallback send");
        require(address(this).balance >= sendValue, "insufficient balance for sendMoney");

        // Observe before state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalanceC = address(c).balance;

        // Trigger fallback by sending Ether (top-level call via address(c).call) --- this is allowed since it's a call on c's address
        (bool okFallback, ) = address(c).call{value: valueToSend}("");

        // Observe after potential fallback
        uint midDeposits = c.depositsCount();
        uint midBalanceC = address(c).balance;

        // Attempt withdraw by this contract (InvMutTest is owner because it deployed C per harness rules)
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Observe after withdraw
        uint postWithdrawBalanceC = address(c).balance;
        uint postWithdrawDeposits = c.depositsCount();

        // Attempt sendMoney by owner
        bool sendMoneyReverted;
        try c.sendMoney(sendTarget, sendValue) {
            sendMoneyReverted = false;
        } catch {
            sendMoneyReverted = true;
        }

        // Final observations
        uint finalBalanceC = address(c).balance;
        uint finalDeposits = c.depositsCount();

        // Define predicates used in the general rule
        bool fallback_amount_received = (midBalanceC == beforeBalanceC + valueToSend);
        bool deposits_incremented_by_one_if_received = (midDeposits == beforeDeposits + (fallback_amount_received ? 1 : 0));

        // If withdrawAmount was <= c's balance at the time of the withdraw call (we approximate using midBalanceC), it must not have reverted.
        // Use midBalanceC as the balance observable right before withdraw call.
        bool withdraw_should_succeed_if_funded = !(withdrawAmount <= midBalanceC && withdrawReverted);

        // If sendMoney did not revert then c's balance must have decreased by at least sendValue (cannot increase because send transfers out value)
        bool sendMoney_balance_decreased_if_succeeded = true;
        if (!sendMoneyReverted) {
            // finalBalanceC should be <= postWithdrawBalanceC - sendValue (postWithdrawBalanceC is the balance before sendMoney)
            // To avoid underflow in the assert we check the arithmetic carefully using <= relation
            sendMoney_balance_decreased_if_succeeded = (postWithdrawBalanceC >= sendValue ? finalBalanceC <= postWithdrawBalanceC - sendValue : finalBalanceC <= postWithdrawBalanceC);
        }

        // Combine into single general assertion about behavior of C for all inputs
        assert(deposits_incremented_by_one_if_received && withdraw_should_succeed_if_funded && sendMoney_balance_decreased_if_succeeded);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: sendTarget (recipient), sendValue (amount to send from c)
    function run(address sendTarget, uint sendValue) public payable {
        require(sendTarget != address(0), "nonzero target");
        // Observe balance of c before any actions
        uint beforeBalanceC = address(c).balance;

        // Attempt sendMoney as owner (InvMutTest deployed C per harness rules)
        bool sendReverted;
        try c.sendMoney(sendTarget, sendValue) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        // Observe balance after the call
        uint afterBalanceC = address(c).balance;

        // General rule asserted for all inputs:
        // - If sendMoney succeeded then beforeBalanceC >= sendValue (it had enough funds), and afterBalanceC <= beforeBalanceC - sendValue.
        // - If sendMoney reverted then we make no claim about balances.
        assert( sendReverted || (beforeBalanceC >= sendValue && afterBalanceC <= beforeBalanceC - sendValue) );
    }

    receive() external payable { }
}
